const moveStay=async({tx,command,actor,at})=>{
 permission(actor,'rooms.operate');const id=command.payload.id,destinationId=command.payload.roomId,reason=string(command.payload.reason,'Room-move reason',{min:3,max:500});if(!uuid(id)||!uuid(destinationId))fail('Choose the active stay and destination room.');const sv=baseline(command,'stays',id,{min:1}),rv=baseline(command,'roomReservations',id,{min:1}),destinationVersion=baseline(command,'rooms',destinationId,{min:1}),preview=await fetchOne(tx,'business_room_reservations',reservationColumns,actor.businessId,id);if(!preview||preview.status!=='CHECKED_IN')problem(409,'ACTIVE_STAY_REQUIRED','Only an active checked-in stay can move rooms.');if(destinationId===preview.roomId)fail('Choose a different destination room.');await advisory(tx,actor.businessId,'hospitality-policy');for(const roomId of [preview.roomId,destinationId].sort())await roomLock(tx,actor.businessId,roomId);const stay=await fetchOne(tx,'business_stays',stayColumns,actor.businessId,id,{lock:true}),reservation=await fetchOne(tx,'business_room_reservations',reservationColumns,actor.businessId,id,{lock:true});if(!stay||!reservation||stay.status!=='CHECKED_IN'||reservation.status!=='CHECKED_IN')problem(409,'ACTIVE_STAY_REQUIRED','Only an active checked-in stay can move rooms.');if(Number(stay.version)!==sv||Number(reservation.version)!==rv)problem(409,'VERSION_CONFLICT','Stay or reservation changed; refresh before moving.');const from=await fetchOne(tx,'business_rooms',roomColumns,actor.businessId,reservation.roomId,{lock:true}),to=await fetchOne(tx,'business_rooms',roomColumns,actor.businessId,destinationId,{lock:true});if(!from||!to||to.housekeepingState!=='READY'||to.maintenanceState!=='AVAILABLE'||Number(to.capacity)<Number(reservation.guests))problem(409,'ROOM_UNAVAILABLE','Destination room must be ready, available and large enough.');if(Number(to.version)!==destinationVersion)problem(409,'VERSION_CONFLICT','Destination room changed; refresh availability.');const sourceVersion=baseline(command,'rooms',from.id,{min:1});if(Number(from.version)!==sourceVersion)problem(409,'VERSION_CONFLICT','Current room changed; refresh before moving this stay.');const occupied=await tx.client.query(`SELECT 1 FROM business_stays WHERE business_id=$1 AND room_id=$2 AND status='CHECKED_IN' LIMIT 1`,[actor.businessId,destinationId]);const blockedUntil=new Date(new Date(reservation.endsAt).getTime()+Number(to.turnaroundMinutes)*60000);const overlap=await tx.client.query(`SELECT 1 FROM business_room_reservations WHERE business_id=$1 AND room_id=$2 AND id<>$3 AND archived_at IS NULL AND status IN ('RESERVED','CHECKED_IN') AND starts_at<$5 AND blocked_until>$4 LIMIT 1`,[actor.businessId,destinationId,id,at,blockedUntil]);const maintenance=await tx.client.query(`SELECT 1 FROM business_room_blocks WHERE business_id=$1 AND room_id=$2 AND status='ACTIVE' AND starts_at<$4 AND (ends_at IS NULL OR ends_at>$3) LIMIT 1`,[actor.businessId,destinationId,at,blockedUntil]);if(occupied.rows.length||overlap.rows.length||maintenance.rows.length)problem(409,'ROOM_UNAVAILABLE','Destination room is occupied, reserved or maintenance-blocked for this interval.');
 const svNext=await tx.bumpEntityVersion(actor.businessId,'stays',id,sv),{rows:stayRows}=await tx.client.query(`UPDATE business_stays SET room_id=$3,version=$4,updated_at=$5 WHERE business_id=$1 AND id=$2 RETURNING ${stayColumns}`,[actor.businessId,id,destinationId,svNext,at]);const rvNext=await tx.bumpEntityVersion(actor.businessId,'roomReservations',id,rv),{rows:resRows}=await tx.client.query(`UPDATE business_room_reservations SET room_id=$3,occupancy_starts_at=$4,blocked_until=$5,turnaround_minutes=$6,version=$7,updated_at=$4 WHERE business_id=$1 AND id=$2 RETURNING ${reservationColumns}`,[actor.businessId,id,destinationId,at,blockedUntil,to.turnaroundMinutes,rvNext]);const fromVersion=await tx.bumpEntityVersion(actor.businessId,'rooms',from.id,Number(from.version)),toVersion=await tx.bumpEntityVersion(actor.businessId,'rooms',to.id,Number(to.version));const oldRoom=(await tx.client.query(`UPDATE business_rooms SET housekeeping_state='DIRTY',housekeeping_at=$3,housekeeping_by=$4,version=$5,updated_by=$4,updated_at=$3 WHERE business_id=$1 AND id=$2 RETURNING ${roomColumns}`,[actor.businessId,from.id,at,actor.staffId,fromVersion])).rows[0];const newRoom=(await tx.client.query(`UPDATE business_rooms SET version=$3,updated_by=$4,updated_at=$5 WHERE business_id=$1 AND id=$2 RETURNING ${roomColumns}`,[actor.businessId,to.id,toVersion,actor.staffId,at])).rows[0];await emit(tx,actor,command,at,{stayId:id,reservationId:id,roomId:destinationId,eventType:'ROOM_MOVE',eventData:{fromRoomId:from.id,toRoomId:to.id,reason}});return {value:record('stays',stayRows[0]),records:[record('stays',stayRows[0]),record('roomReservations',resRows[0]),record('rooms',oldRoom),record('rooms',newRoom)]};
};

const printFolio=async({tx,command,actor,at})=>{
 permission(actor,'folio.view');const id=command.payload.id;if(!uuid(id))fail('Choose a guest folio.');const folio=await fetchOne(tx,'business_folios',folioColumns,actor.businessId,id);if(!folio)problem(404,'FOLIO_NOT_FOUND','Guest folio was not found.');const reservation=await fetchOne(tx,'business_room_reservations',reservationColumns,actor.businessId,id);const entries=await projectRows(tx.client,actor.businessId,'business_folio_entries',entryColumns,'folioEntries',{where:'AND folio_id=$2',params:[id],order:'posted_at,id'});const customer=await fetchOne(tx,'business_customers','id,name,phone,email',actor.businessId,folio.customerId);const snapshot={documentType:'GUEST_FOLIO',documentNumber:`FOL-${command.commandId.slice(0,8).toUpperCase()}`,layoutVersion:1,folio:record('folios',folio).data,reservation:reservation?record('roomReservations',reservation).data:null,guest:customer,entries:entries.map(row=>row.data),issuedAt:at.toISOString()};const hash=documentHash(snapshot),docId=randomUUID();await tx.client.query(`INSERT INTO business_documents(business_id,id,document_type,document_number,layout_version,snapshot,snapshot_hash,source_command_id,issued_by,issued_at) VALUES($1,$2,'GUEST_FOLIO',$3,1,$4::jsonb,$5,$6,$7,$8)`,[actor.businessId,docId,snapshot.documentNumber,JSON.stringify(snapshot),hash,command.commandId,actor.staffId,at]);const doc={collection:'businessDocuments',id:docId,version:1,archived:false,data:{id:docId,type:'GUEST_FOLIO',documentNumber:snapshot.documentNumber,layoutVersion:1,hash,snapshot,issuedAt:at.toISOString()}};const print=await queueDocumentPrint(tx,{businessId:actor.businessId,documentId:docId,printerRole:'OFFICE',staffId:actor.staffId,at});return {value:doc,records:[doc,print]};
};

const resolveMaintenance=async({tx,command,actor,at})=>{
 permission(actor,'maintenance.manage');const id=command.payload.id;if(!uuid(id))fail('Choose an open maintenance work order.');const v=baseline(command,'maintenanceWorkOrders',id,{min:1});const work=await fetchOne(tx,'business_maintenance_work_orders','id,room_id AS "roomId",block_id AS "blockId",title,fault,status,opened_by AS "openedBy",opened_at AS "openedAt",resolved_by AS "resolvedBy",resolved_at AS "resolvedAt",resolution,version',actor.businessId,id,{lock:true});if(!work||work.status!=='OPEN')problem(409,'WORK_ORDER_NOT_OPEN','Only open maintenance work can be resolved.');if(Number(work.version)!==v)problem(409,'VERSION_CONFLICT','Work order changed; refresh it before resolving.');const resolution=string(command.payload.resolution,'Resolution',{min:3,max:1000});const next=await tx.bumpEntityVersion(actor.businessId,'maintenanceWorkOrders',id,v);const {rows}=await tx.client.query(`UPDATE business_maintenance_work_orders SET status='RESOLVED',resolved_by=$3,resolved_at=$4,resolution=$5,version=$6 WHERE business_id=$1 AND id=$2 RETURNING id,room_id AS "roomId",block_id AS "blockId",title,fault,status,opened_by AS "openedBy",opened_at AS "openedAt",resolved_by AS "resolvedBy",resolved_at AS "resolvedAt",resolution,version,NULL::timestamptz AS "archivedAt"`,[actor.businessId,id,actor.staffId,at,resolution,next]);const block=await fetchOne(tx,'business_room_blocks','id,room_id AS "roomId",work_order_id AS "workOrderId",starts_at AS "startsAt",ends_at AS "endsAt",reason,status,source_command_id AS "sourceCommandId",created_by AS "createdBy",created_at AS "createdAt",resolved_by AS "resolvedBy",resolved_at AS "resolvedAt",1::bigint AS version,NULL::timestamptz AS "archivedAt"',actor.businessId,work.blockId,{lock:true});await tx.client.query(`UPDATE business_room_blocks SET status='RESOLVED',ends_at=$3,resolved_by=$4,resolved_at=$3 WHERE business_id=$1 AND id=$2`,[actor.businessId,work.blockId,at,actor.staffId]);const room=await fetchOne(tx,'business_rooms',roomColumns,actor.businessId,work.roomId,{lock:true});return {value:record('maintenanceWorkOrders',rows[0]),records:[record('maintenanceWorkOrders',rows[0]),record('roomBlocks',{...block,status:'RESOLVED',endsAt:at,resolvedBy:actor.staffId,resolvedAt:at}),record('rooms',room)]};
};

const openMaintenance=async({tx,command,actor,at})=>{
 permission(actor,'maintenance.manage');const p=command.payload,id=p.id,roomId=p.roomId;if(!uuid(id)||!uuid(roomId))fail('Choose a work-order and room ID.');const v=baseline(command,'rooms',roomId,{min:1});await roomLock(tx,actor.businessId,roomId);const room=await fetchOne(tx,'business_rooms',roomColumns,actor.businessId,roomId,{lock:true});if(!room||Number(room.version)!==v)problem(409,'VERSION_CONFLICT','Room changed; refresh before opening maintenance.');if(room.maintenanceState==='OUT_OF_SERVICE')problem(409,'ROOM_ALREADY_BLOCKED','Room already has an active maintenance block.');const activeBooking=await tx.client.query(`SELECT 1 FROM business_room_reservations WHERE business_id=$1 AND room_id=$2 AND archived_at IS NULL AND status IN ('RESERVED','CHECKED_IN') AND blocked_until>$3 LIMIT 1`,[actor.businessId,roomId,at]);if(activeBooking.rows.length)problem(409,'ROOM_HAS_BOOKINGS','Resolve or relocate active and future bookings before blocking this room.');const title=string(p.title,'Work-order title'),fault=string(p.fault,'Fault description',{min:3,max:1000}),reason=string(p.reason||fault,'Room block reason',{min:3,max:1000});const blockId=randomUUID(),workVersion=await tx.bumpEntityVersion(actor.businessId,'maintenanceWorkOrders',id,0);const nextRoom=await tx.bumpEntityVersion(actor.businessId,'rooms',roomId,v);const until=p.endsAt?new Date(p.endsAt):null;if(until&&!Number.isFinite(until.getTime())||until&&until<=at)fail('Maintenance end time must be in the future.');const {rows:blockRows}=await tx.client.query(`INSERT INTO business_room_blocks(business_id,id,room_id,starts_at,ends_at,reason,status,source_command_id,created_by,created_at) VALUES($1,$2,$3,$4,$5,$6,'ACTIVE',$7,$8,$4) RETURNING id,room_id AS "roomId",work_order_id AS "workOrderId",starts_at AS "startsAt",ends_at AS "endsAt",reason,status,source_command_id AS "sourceCommandId",created_by AS "createdBy",created_at AS "createdAt",resolved_by AS "resolvedBy",resolved_at AS "resolvedAt",1::bigint AS version,NULL::timestamptz AS "archivedAt"`,[actor.businessId,blockId,roomId,at,until,reason,command.commandId,actor.staffId]);const {rows:workRows}=await tx.client.query(`INSERT INTO business_maintenance_work_orders(business_id,id,room_id,block_id,title,fault,status,opened_by,opened_at,version) VALUES($1,$2,$3,$4,$5,$6,'OPEN',$7,$8,$9) RETURNING id,room_id AS "roomId",block_id AS "blockId",title,fault,status,opened_by AS "openedBy",opened_at AS "openedAt",resolved_by AS "resolvedBy",resolved_at AS "resolvedAt",resolution,version,NULL::timestamptz AS "archivedAt"`,[actor.businessId,id,roomId,blockId,title,fault,actor.staffId,at,workVersion]);await tx.client.query('UPDATE business_room_blocks SET work_order_id=$3 WHERE business_id=$1 AND id=$2',[actor.businessId,blockId,id]);const {rows:roomRows}=await tx.client.query(`UPDATE business_rooms SET maintenance_state='OUT_OF_SERVICE',housekeeping_state='OUT_OF_SERVICE',version=$3,updated_by=$4,updated_at=$5 WHERE business_id=$1 AND id=$2 RETURNING ${roomColumns}`,[actor.businessId,roomId,nextRoom,actor.staffId,at]);return {value:record('maintenanceWorkOrders',workRows[0]),records:[record('maintenanceWorkOrders',workRows[0]),record('roomBlocks',blockRows[0]),record('rooms',roomRows[0])]};
};

const returnToService=async({tx,command,actor,at})=>{
 permission(actor,'maintenance.manage');const roomId=command.payload.id;if(!uuid(roomId))fail('Choose a room.');const v=baseline(command,'rooms',roomId,{min:1});await roomLock(tx,actor.businessId,roomId);const room=await fetchOne(tx,'business_rooms',roomColumns,actor.businessId,roomId,{lock:true});if(!room||Number(room.version)!==v)problem(409,'VERSION_CONFLICT','Room changed; refresh before returning it to service.');if(room.maintenanceState!=='OUT_OF_SERVICE')problem(409,'ROOM_NOT_OUT_OF_SERVICE','The room is not blocked for maintenance.');const pending=await tx.client.query(`SELECT 1 FROM business_maintenance_work_orders WHERE business_id=$1 AND room_id=$2 AND status='OPEN' LIMIT 1`,[actor.businessId,roomId]);if(pending.rows.length)problem(409,'OPEN_WORK_ORDER','Resolve every open maintenance work order before returning the room to service.');const version=await tx.bumpEntityVersion(actor.businessId,'rooms',roomId,v);const {rows}=await tx.client.query(`UPDATE business_rooms SET maintenance_state='AVAILABLE',housekeeping_state='DIRTY',version=$3,updated_by=$4,updated_at=$5,housekeeping_at=$5,housekeeping_by=$4 WHERE business_id=$1 AND id=$2 RETURNING ${roomColumns}`,[actor.businessId,roomId,version,actor.staffId,at]);return {value:record('rooms',rows[0]),records:[record('rooms',rows[0])]};
};

export const hospitalityCommandRegistry=new Map([
 ['hospitality.settings.save',{permission:'business.configure',offlinePolicy:'ONLINE_ONLY',handler:settingsSave}],
 ['hotelService.save',{permission:'business.configure',offlinePolicy:'ONLINE_ONLY',handler:saveHotelService}],
 ['roomReservation.modify',{permission:'rooms.operate',offlinePolicy:'ONLINE_ONLY',handler:reservationModify}],
 ['roomReservation.confirmation',{permission:'rooms.operate',offlinePolicy:'ONLINE_ONLY',handler:reservationConfirmation}],
 ['folio.open',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:openFolio}],
 ['folio.postAccommodation',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:postAccommodation}],
 ['folio.postService',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:folioAction('service')}],
 ['folio.pay',{permission:'folio.manage',permissionAny:['folio.manage','payment.record'],offlinePolicy:'ONLINE_ONLY',handler:folioAction('pay')}],
 ['folio.deposit',{permission:'folio.manage',permissionAny:['folio.manage','payment.record'],offlinePolicy:'ONLINE_ONLY',handler:folioAction('deposit')}],
 ['folio.applyDeposit',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:folioAction('applyDeposit')}],
 ['folio.adjust',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:folioAction('adjust')}],
 ['folio.reverse',{permission:'folio.manage',approvalPermission:'folio.reverse',offlinePolicy:'ONLINE_ONLY',handler:folioAction('reverse')}],
 ['folio.print',{permission:'folio.view',permissionAny:['folio.view','folio.manage'],offlinePolicy:'ONLINE_ONLY',handler:printFolio}],
 ['stay.checkIn',{permission:'rooms.operate',offlinePolicy:'ONLINE_ONLY',handler:checkIn}],
 ['stay.checkOut',{permission:'rooms.operate',permissionAny:['rooms.operate','folio.manage'],offlinePolicy:'ONLINE_ONLY',handler:checkOut}],
 ['stay.move',{permission:'rooms.operate',offlinePolicy:'ONLINE_ONLY',handler:moveStay}],
 ['stay.extend',{permission:'folio.manage',offlinePolicy:'ONLINE_ONLY',handler:extendStay}],
 ['maintenance.open',{permission:'maintenance.manage',offlinePolicy:'ONLINE_ONLY',handler:openMaintenance}],
 ['maintenance.resolve',{permission:'maintenance.manage',offlinePolicy:'ONLINE_ONLY',handler:resolveMaintenance}],
 ['maintenance.returnToService',{permission:'maintenance.manage',offlinePolicy:'ONLINE_ONLY',handler:returnToService}],
]);

export const hospitalityWalkInHandler=baseWalkIn=>async input=>walkIn({...input,baseWalkIn});
